import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, session, g
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        email TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin:superSecret2024!').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email, department) VALUES (?, ?, 'admin', 'admin@corp.local', 'IT')",
               ('admin', admin_hash))
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'Authentication required'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username', '')
    password = data.get('password', '')

    db = get_db()
    password_hash = hashlib.sha256(f"{username}:{password}".encode()).hexdigest()

    # Parameterized query for login - this is safe
    user = db.execute(
        "SELECT * FROM users WHERE username = ? AND password_hash = ?",
        (username, password_hash)
    ).fetchone()

    if user:
        session['user_id'] = user['id']
        session['role'] = user['role']
        return jsonify({'message': 'Login successful', 'role': user['role']})
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/api/users/search', methods=['GET'])
@require_auth
def search_users():
    """Search users by department or role. Supports flexible filtering."""
    department = request.args.get('department', '')
    role_filter = request.args.get('role', '')
    sort_by = request.args.get('sort', 'username')

    # Basic input length check
    if len(department) > 100 or len(role_filter) > 50:
        return jsonify({'error': 'Input too long'}), 400

    db = get_db()

    # Build query with filters
    query = "SELECT id, username, email, department, role FROM users WHERE 1=1"

    if department:
        query += f" AND department = '{department}'"
    if role_filter:
        query += f" AND role = '{role_filter}'"

    # Validate sort column against allowlist
    allowed_sorts = ['username', 'email', 'department', 'role', 'id']
    if sort_by not in allowed_sorts:
        sort_by = 'username'
    query += f" ORDER BY {sort_by}"

    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute("INSERT INTO audit_log (action, user_id) VALUES (?, ?)",
                   (f"search:dept={department}", session.get('user_id')))
        db.commit()

        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
@require_auth
def get_user(user_id):
    db = get_db()
    user = db.execute(
        "SELECT id, username, email, department, role FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
